package io.github.matosoe.controlehoras.ui.today;
import android.os.Bundle; import android.view.View; import android.widget.TextView; import androidx.fragment.app.Fragment; import java.time.LocalDate; import java.time.format.DateTimeFormatter; import io.github.matosoe.controlehoras.R;
public class TodayFragment extends Fragment { private LocalDate selected=LocalDate.now(); private TextView title,summary; public TodayFragment(){super(R.layout.fragment_today);} @Override public void onViewCreated(View v,Bundle s){title=v.findViewById(R.id.today_title);summary=v.findViewById(R.id.today_summary);v.findViewById(R.id.previous_day).setOnClickListener(x->{selected=selected.minusDays(1);render();});v.findViewById(R.id.next_day).setOnClickListener(x->{selected=selected.plusDays(1);render();});render();} private void render(){title.setText(selected.format(DateTimeFormatter.ofPattern("dd/MM/yyyy")));summary.setText("Carregando lançamentos do dia selecionado...");}}
